<?php require_once 'config/auth.php'; require_admin(); $pageTitle='Reportes';
$rows=$pdo->query("SELECT p.codigo,p.nombre,c.nombre categoria,p.stock_actual,p.stock_minimo,p.precio_referencia,COALESCE(SUM(CASE WHEN m.tipo='entrada' THEN m.cantidad ELSE 0 END),0) entradas,COALESCE(SUM(CASE WHEN m.tipo='salida' THEN m.cantidad ELSE 0 END),0) salidas FROM producto p JOIN categoria c ON c.id_categoria=p.id_categoria LEFT JOIN movimiento m ON m.id_producto=p.id_producto WHERE p.estado=1 GROUP BY p.id_producto ORDER BY p.nombre")->fetchAll();
$recs=[];foreach($rows as $r){$sal=(int)$r['salidas'];$promedio=$sal/30;$objetivo=max((int)$r['stock_minimo'],(int)ceil($promedio*7));$sugerido=max(0,$objetivo-(int)$r['stock_actual']);if($sugerido>0)$recs[]=['producto'=>$r['nombre'],'stock'=>$r['stock_actual'],'min'=>$r['stock_minimo'],'promedio'=>$promedio,'sugerido'=>$sugerido];}require 'partials/header.php'; ?>
<div class="page-head"><div><span class="eyebrow">ANÁLISIS</span><h1>Reportes y apoyo a decisiones</h1><p>Resumen de inventario y una recomendación básica de reposición basada en salidas acumuladas.</p></div><button class="btn secondary" onclick="window.print()">Imprimir</button></div><section class="stats"><div class="stat"><span>Productos analizados</span><strong><?=count($rows)?></strong></div><div class="stat warning"><span>Productos a reponer</span><strong><?=count($recs)?></strong></div></section><div class="two-col"><section class="panel"><div class="panel-head"><h2>Inventario y movimientos</h2></div><div class="table-wrap"><table><thead><tr><th>Producto</th><th>Stock</th><th>Mínimo</th><th>Entradas</th><th>Salidas</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=e($r['nombre'])?></b><small><?=e($r['codigo'])?> · <?=e($r['categoria'])?></small></td><td><?=e((string)$r['stock_actual'])?></td><td><?=e((string)$r['stock_minimo'])?></td><td><?=e((string)$r['entradas'])?></td><td><?=e((string)$r['salidas'])?></td></tr><?php endforeach;?></tbody></table></div></section><section class="panel"><div class="panel-head"><h2>Recomendaciones</h2></div><?php if(!$recs):?><div class="empty">No se identificaron necesidades de reposición con el criterio actual.</div><?php else:?><div class="recommendations"><?php foreach($recs as $r):?><div class="recommendation"><div><b><?=e($r['producto'])?></b><small>Stock <?=e((string)$r['stock'])?> · mínimo <?=e((string)$r['min'])?></small></div><strong>+<?=e((string)$r['sugerido'])?></strong></div><?php endforeach;?></div><?php endif;?><p class="muted note">Criterio MVP: se usa la salida acumulada de los últimos datos disponibles como referencia de consumo, con horizonte aproximado de 7 días y respetando el stock mínimo. Es una heurística de apoyo, no una predicción estadística.</p></section></div><?php require 'partials/footer.php'; ?>
